package com.learn.hub.actuator;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

import com.learn.hub.config.LearnHubProperties;
import org.springframework.boot.actuate.health.Health;
import org.springframework.boot.actuate.health.HealthIndicator;
import org.springframework.stereotype.Component;

/** 内容目录不可读时让 health 变 DOWN，避免进程活着但功能已废。 */
@Component("contentDir")
public class ContentDirHealthIndicator implements HealthIndicator {

    private final Path contentDir;

    public ContentDirHealthIndicator(LearnHubProperties props) {
        this.contentDir = Path.of(props.contentDir());
    }

    @Override
    public Health health() {
        if (!Files.isDirectory(contentDir)) {
            return Health.down().withDetail("path", contentDir).build();
        }
        try (var files = Files.list(contentDir)) {
            long count = files.filter(p -> p.toString().endsWith(".json")).count();
            return Health.up().withDetail("topics", count).build();
        } catch (IOException e) {
            return Health.down(e).withDetail("path", contentDir).build();
        }
    }
}
